CREATE TABLE IF NOT EXISTS roles (code VARCHAR(16) PRIMARY KEY, name VARCHAR(32) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
 id VARCHAR(64) PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(40) NOT NULL,
 password_hash VARCHAR(256) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'student',
 avatar VARCHAR(512) NOT NULL DEFAULT '', bio VARCHAR(500) NOT NULL DEFAULT '', points INT NOT NULL DEFAULT 0,
 status ENUM('active','banned') NOT NULL DEFAULT 'active', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY (role) REFERENCES roles(code), INDEX idx_user_role_status(role,status), INDEX idx_user_points(points)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (
 token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, csrf_token CHAR(64) NOT NULL,
 expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_session_expiry(expires_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(64) PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, icon VARCHAR(40) NOT NULL, color VARCHAR(16) NOT NULL, description VARCHAR(200) NOT NULL DEFAULT '') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS posts (
 id VARCHAR(64) PRIMARY KEY, author_id VARCHAR(64) NOT NULL, category_id VARCHAR(64) NOT NULL,
 title VARCHAR(120) NOT NULL, content MEDIUMTEXT NOT NULL, tags JSON NOT NULL, type VARCHAR(20) NOT NULL,
 image VARCHAR(512) NULL, views INT UNSIGNED NOT NULL DEFAULT 0, featured BOOLEAN NOT NULL DEFAULT FALSE, pinned BOOLEAN NOT NULL DEFAULT FALSE,
 status ENUM('published','pending') NOT NULL DEFAULT 'published', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id),
 INDEX idx_post_category_time(category_id,created_at), INDEX idx_post_status_time(status,created_at), INDEX idx_post_author(author_id), FULLTEXT INDEX ft_post_content(title,content)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_comments (
 id VARCHAR(64) PRIMARY KEY, post_id VARCHAR(64) NOT NULL, author_id VARCHAR(64) NOT NULL, parent_id VARCHAR(64) NULL,
 content TEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(parent_id) REFERENCES post_comments(id) ON DELETE CASCADE, INDEX idx_comment_post_time(post_id,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_likes (post_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_favorites (post_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS browsing_history (user_id VARCHAR(64) NOT NULL,post_id VARCHAR(64) NOT NULL,visited_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,post_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS questions (
 id VARCHAR(64) PRIMARY KEY, author_id VARCHAR(64) NOT NULL, category_id VARCHAR(64) NOT NULL, title VARCHAR(120) NOT NULL, content MEDIUMTEXT NOT NULL, tags JSON NOT NULL,
 accepted_answer_id VARCHAR(64) NULL, views INT UNSIGNED NOT NULL DEFAULT 0, bounty INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_question_category_time(category_id,created_at), INDEX idx_question_author(author_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS answers (id VARCHAR(64) PRIMARY KEY,question_id VARCHAR(64) NOT NULL,author_id VARCHAR(64) NOT NULL,content MEDIUMTEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id),INDEX idx_answer_question(question_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS answer_comments (id VARCHAR(64) PRIMARY KEY,answer_id VARCHAR(64) NOT NULL,author_id VARCHAR(64) NOT NULL,content TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(answer_id) REFERENCES answers(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS answer_likes (answer_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,PRIMARY KEY(answer_id,user_id),FOREIGN KEY(answer_id) REFERENCES answers(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS question_favorites (question_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,PRIMARY KEY(question_id,user_id),FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS courses (
 id VARCHAR(64) PRIMARY KEY,teacher_id VARCHAR(64) NOT NULL,category_id VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,subtitle VARCHAR(150) NOT NULL,description TEXT NOT NULL,
 image VARCHAR(512) NOT NULL DEFAULT '',visual VARCHAR(20) NOT NULL DEFAULT 'spring',badge VARCHAR(20) NOT NULL DEFAULT '新课',rating DECIMAL(2,1) NOT NULL DEFAULT 0,hours INT UNSIGNED NOT NULL,level VARCHAR(16) NOT NULL,tags JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(teacher_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id),INDEX idx_course_category(category_id),INDEX idx_course_teacher(teacher_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS course_chapters (id VARCHAR(64) PRIMARY KEY,course_id VARCHAR(64) NOT NULL,title VARCHAR(150) NOT NULL,content MEDIUMTEXT NOT NULL,duration VARCHAR(40) NOT NULL,position INT UNSIGNED NOT NULL,UNIQUE KEY uq_chapter_position(course_id,position),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS course_enrollments (user_id VARCHAR(64) NOT NULL,course_id VARCHAR(64) NOT NULL,last_chapter_id VARCHAR(64) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,course_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS learning_progress (user_id VARCHAR(64) NOT NULL,course_id VARCHAR(64) NOT NULL,chapter_id VARCHAR(64) NOT NULL,completed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,chapter_id),FOREIGN KEY(user_id,course_id) REFERENCES course_enrollments(user_id,course_id) ON DELETE CASCADE,FOREIGN KEY(chapter_id) REFERENCES course_chapters(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resources (
 id VARCHAR(64) PRIMARY KEY,author_id VARCHAR(64) NOT NULL,category_id VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,type VARCHAR(12) NOT NULL,
 byte_size INT UNSIGNED NOT NULL,filename VARCHAR(255) NOT NULL,storage_key VARCHAR(255) NOT NULL UNIQUE,mime VARCHAR(100) NOT NULL,tags JSON NOT NULL,status ENUM('approved','pending','rejected') NOT NULL DEFAULT 'pending',downloads INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id),INDEX idx_resource_status(status,category_id,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resource_favorites (resource_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,PRIMARY KEY(resource_id,user_id),FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resource_downloads (id VARCHAR(64) PRIMARY KEY,resource_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS point_rules (code VARCHAR(20) PRIMARY KEY,amount INT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS checkins (user_id VARCHAR(64) NOT NULL,day DATE NOT NULL,PRIMARY KEY(user_id,day),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS point_records (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,event_key VARCHAR(150) NOT NULL,reason VARCHAR(120) NOT NULL,amount INT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_point_event(user_id,event_key),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_point_user_time(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,title VARCHAR(150) NOT NULL,content TEXT NOT NULL,type VARCHAR(20) NOT NULL,link VARCHAR(255) NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_notification_unread(user_id,is_read,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements (id VARCHAR(64) PRIMARY KEY,title VARCHAR(150) NOT NULL,content TEXT NOT NULL,type VARCHAR(20) NOT NULL,pinned BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_operation_logs (id VARCHAR(64) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,action VARCHAR(500) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX idx_audit_time(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_conversations (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,messages JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seed_runs (name VARCHAR(80) PRIMARY KEY,completed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
